            private static bool TryReadStableJournalDelta(
                string filePath,
                long previousOffset,
                out byte[] data,
                out long nextOffset)
            {
                return JournalReadService.TryReadDeltaNonBlocking(filePath, previousOffset, out data, out nextOffset, maxAttempts: 3);
            }
