            public void StartMonitoring()
            {
            string dir = Path.GetDirectoryName(_sourcePath);
            string filter = Path.GetFileName(_sourcePath);
    
            if (_atmType == ATMType.NCR)
            {
                // NCR uses fixed files
                MonitorFile(_sourcePath);
            }
            else
            {
                // GRG/WN use daily files
                _watcher = new FileSystemWatcher(dir);
                _watcher.NotifyFilter = NotifyFilters.FileName | NotifyFilters.Size | NotifyFilters.LastWrite;
