                    fs.Read(buffer, 0, buffer.Length);
    
                    // Save to local backup (Mirroring)
                    string backupFile = Path.Combine(_backupPath, Path.GetFileName(path) + ".bak");
                    using (FileStream bfs = new FileStream(backupFile, FileMode.Append, FileAccess.Write, FileShare.ReadWrite))
                    {
                    bfs.Write(buffer, 0, buffer.Length);
                    }
    
                    // Trigger event for network transmission
                    OnNewDataCaptured?.Invoke(buffer, Path.GetFileName(path));
    
                    _lastPosition = fs.Size;
                }
                }
            }
            catch (Exception ex)
            {
                // Log error
            }
            }
    
    
