            {
            if (!_isRunning) return;
            Thread.Sleep(1000); // Wait for file creation to complete
            Log("New EJ file detected: " + e.Name);
            ProcessFile(e.FullPath);
            }
            private void ProcessFile(string filePath)
            {
            try
            {
                if (!File.Exists(filePath)) return;
                FileInfo fi = new FileInfo(filePath);
                if (fi.Length <= _lastProcessedSize && fi.FullName == GetPrimaryFile())
                return; // No new data
                byte[] newData;
                using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                if (fi.FullName == GetPrimaryFile())
                {
                    fs.Seek(_lastProcessedSize, SeekOrigin.Begin);
                    newData = new byte[fi.Length - _lastProcessedSize];
                    fs.Read(newData, 0, newData.Length);
                    _lastProcessedSize = fi.Length;
                }
                else
                {
                    newData = new byte[fi.Length];
                    fs.Read(newData, 0, newData.Length);
                }
                }
                if (newData.Length > 0)
                {
                Log("Processing " + newData.Length + " bytes from " + Path.GetFileName(filePath));
                AnalyzeContent(Encoding.Default.GetString(newData));
                // Backup locally
                BackupLocally(filePath, newData);
                // Notify data ready for sending
                if (OnDataReady != null)
                    OnDataReady(newData);
                }
            }
            catch (Exception ex)
            {
                Log("ERROR processing file: " + ex.Message);
            }
            }
            private string GetPrimaryFile()
            {
            switch (_atmType)
            {
                case ATMType.NCR: return Path.Combine(_ejPath, "EJDATA.LOG");
                case ATMType.GRG: return Path.Combine(_ejPath, "EJ" + DateTime.Now.ToString("yyyyMMdd") + ".log");
                case ATMType.WN: return Path.Combine(_ejPath, "EJ" + DateTime.Now.ToString("yyyyMMdd") + ".log");
                default: return "";
            }
            }
            private void AnalyzeContent(string content)
            {
            // Analyze journal content for ATM status
            string upper = content.ToUpper();
            if (upper.Contains("SUPERVISOR") || upper.Contains("SUPV MODE"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.ConnectedOnly);
                Log("Status: Supervisor Mode detected");
            }
            else if (upper.Contains("FAULT") || upper.Contains("ERROR") || upper.Contains("HARDWARE"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.CriticalFault);
                Log("Status: Fault detected in journal");
            }
            else if (upper.Contains("OUT OF SERVICE") || upper.Contains("OOS"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.OutOfService);
                Log("Status: Out of Service");
            }
            else if (upper.Contains("IN SERVICE") || upper.Contains("READY"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.InService);
                Log("Status: In Service");
            }
            }
            private void BackupLocally(string sourceFile, byte[] data)
            {
            try
            {
                string backupDir = Path.Combine(Constants.Paths.LocalBackupBase, _atmId, DateTime.Now.ToString("yyyy-MM"));
                if (!Directory.Exists(backupDir))
                Directory.CreateDirectory(backupDir);
                string backupFile = Path.Combine(backupDir, Path.GetFileName(sourceFile));
                File.WriteAllBytes(backupFile, data);
            }
            catch (Exception ex)
            {
                Log("Backup error: " + ex.Message);
            }
            }
            public bool VerifyIntegrity(string filePath)
            {
            try
            {
                string sourceHash = ComputeMD5(filePath);
                string backupPath = Path.Combine(Constants.Paths.LocalBackupBase, _atmId, DateTime.Now.ToString("yyyy-MM"), Path.GetFileName(filePath));
                if (!File.Exists(backupPath))
                {
                Log("Verification FAILED: Backup file not found.");
                return false;
                }
                string backupHash = ComputeMD5(backupPath);
                bool match = sourceHash == backupHash;
                Log("Verification " + (match ? "PASSED" : "FAILED") + ": Source=" + sourceHash.Substring(0, 8) + " Backup=" + backupHash.Substring(0, 8));
                return match;
            }
            catch (Exception ex)
            {
                Log("Verification error: " + ex.Message);
                return false;
            }
            }
            private string ComputeMD5(string filePath)
            {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(filePath))
            {
                byte[] hash = md5.ComputeHash(stream);
                StringBuilder sb = new StringBuilder();
                foreach (byte b in hash) sb.Append(b.ToString("x2"));
                return sb.ToString();
            }
            }
            private void Log(string message)
            {
            OnLogMessage?.Invoke(message);
            }
            private readonly TimeSpan _ackTimeout = TimeSpan.FromSeconds(Math.Max(30, AppConstants.HeartbeatTimeoutSec));
            public void Start()
            {
            if (_running) return;
            _running = true;
            _processorThread = new Thread(ProcessLoop)
            {
                IsBackground = true,
                Name = "EJLive.JournalProcessor"
            };
            _processorThread.Start();
            AppLogger.Instance.Info("JournalProcessor started", "Processor");
            }
            public void Stop()
            {
            _running = false;
            AppLogger.Instance.Info("JournalProcessor stopped", "Processor");
            }
            public void Pause()
            {
            _paused = true;
            Log("JournalProcessor paused.");
            }
            public void Resume()
            {
            _paused = false;
            Log("JournalProcessor resumed.");
            }
            public void ForceSendNow()
            {
            _paused = false;
            }
            public bool VerifyIntegrity(string filePath)
            {
            if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
                return false;
            try
            {
                var sourceHash = ComputeFileMd5(filePath);
                var backupRoot = GetBackupRoot();
                if (!Directory.Exists(backupRoot))
                return false;
                var fileName = Path.GetFileName(filePath);
                var backupCandidates = Directory.EnumerateFiles(backupRoot, fileName + ".*.bin", SearchOption.AllDirectories)
                .OrderByDescending(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
                if (backupCandidates.Length == 0)
                return false;
                var backupHash = ComputeFileMd5(backupCandidates[0]);
                return string.Equals(sourceHash, backupHash, StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
            }
            private void ProcessQueueLoop()
            {
            while (_running)
            {
                try
                {
                SweepAckTimeouts();
                if (_paused || _network == null || _outbox == null || !_network.IsConnected)
                {
                    Thread.Sleep(250);
                    continue;
                }
                if (!_outbox.TryDequeue(out var item))
                {
                    Thread.Sleep(200);
                    continue;
                }
                if (!item.IsReadyToSend)
                {
                    _outbox.Enqueue(item);
                    Thread.Sleep(120);
                    continue;
                }
                SendOutboxItem(item);
                }
                catch (Exception ex)
                {
                Log("Queue loop error: " + ex.Message);
                Thread.Sleep(500);
                }
            }
            }
            private void SendOutboxItem(JournalOutboxItem item)
            {
            if (_network == null || _outbox == null)
                return;
            try
            {
                var checksum = string.IsNullOrWhiteSpace(item.Checksum)
                ? SecurityHelper.SHA256Hash(item.Data)
                : item.Checksum;
                ReportProgress(item.ATM_ID, item.FileName, 0, 0, item.Data.LongLength, SyncStatus.InProgress);
                var sent = _network.SendJournalFile(item.FileName, item.Data, item.Offset, checksum);
                if (sent)
                {
                _outbox.MarkAwaitingAcknowledgement(item.ItemId, _ackTimeout);
                TotalSent++;
                OnItemDispatched?.Invoke(this, item);
                ReportProgress(item.ATM_ID, item.FileName, item.Data.LongLength, item.Data.LongLength, item.Data.LongLength, SyncStatus.Syncing);
                }
                else
                {
                var delay = _retryPolicy.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                TotalFailed++;
                OnItemFailed?.Invoke(this, item);
                ReportProgress(item.ATM_ID, item.FileName, 0, 0, item.Data.LongLength, SyncStatus.Failed);
                }
            }
            catch (Exception ex)
            {
                _outbox.RetryItem(item.ItemId, _retryPolicy.ComputeDelay(item.RetryCount + 1));
                TotalFailed++;
                OnItemFailed?.Invoke(this, item);
                Log("Send item error: " + ex.Message);
            }
            }
            public bool ApplyAcknowledgement(string ackText, out JournalOutboxItem? item, out bool success, out string detail)
            {
            item = null;
            success = false;
            detail = string.Empty;
            if (_outbox == null)
                return false;
            if (!_outbox.TryApplyAcknowledgement(ackText, _retryPolicy, out var resolved, out success, out detail))
                return false;
            item = resolved;
            if (success)
            {
                resolved.Status = SyncStatus.Completed;
                resolved.LastAckDetail = detail;
                OnItemCompleted?.Invoke(this, resolved);
                ReportProgress(resolved.ATM_ID, resolved.FileName, resolved.SizeBytes, resolved.SizeBytes, resolved.SizeBytes, SyncStatus.Completed);
            }
            else
            {
                resolved.Status = SyncStatus.Failed;
                resolved.LastAckDetail = detail;
                OnItemFailed?.Invoke(this, resolved);
                ReportProgress(resolved.ATM_ID, resolved.FileName, 0, 0, resolved.SizeBytes, SyncStatus.Failed);
            }
            return true;
            }
            private void SweepAckTimeouts()
            {
            if (_outbox == null)
                return;
            var now = DateTime.UtcNow;
            if ((now - _lastAckSweepUtc) < TimeSpan.FromSeconds(5))
                return;
            _lastAckSweepUtc = now;
            var requeued = _outbox.RequeueTimedOutAcknowledgements(_retryPolicy, maxItems: 20);
            if (requeued > 0)
                Log($"Acknowledgement timeout recovery requeued {requeued} item(s).");
            }
            private void ConfigureWatcher()
            {
            _watcher?.Dispose();
            _watcher = new FileSystemWatcher(_watchPath)
            {
                IncludeSubdirectories = false,
                NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite | NotifyFilters.Size,
                Filter = "*.*",
                EnableRaisingEvents = true
            };
            _watcher.Created += (_, e) => ProcessWatchFileSafely(e.FullPath, fullRead: true);
            _watcher.Changed += (_, e) => ProcessWatchFileSafely(e.FullPath, fullRead: false);
            _watcher.Renamed += (_, e) => ProcessWatchFileSafely(e.FullPath, fullRead: true);
            }
            private void ScanExistingFiles()
            {
            foreach (var path in Directory.EnumerateFiles(_watchPath))
            {
                ProcessWatchFileSafely(path, fullRead: true);
            }
            }
            private void ProcessWatchFileSafely(string filePath, bool fullRead)
            {
            if (!_running || _paused)
                return;
            if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
                return;
            if (!IsSupportedWatchFile(filePath))
                return;
            try
            {
                Thread.Sleep(80);
                ProcessWatchFile(filePath, fullRead);
            }
            catch (Exception ex)
            {
                Log("Watch file error: " + ex.Message);
            }
            }
            private void ProcessWatchFile(string filePath, bool fullRead)
            {
            var previousOffset = 0L;
            if (!fullRead && _fileOffsets.TryGetValue(filePath, out var existingOffset))
                previousOffset = existingOffset;
            if (!TryReadStableJournalDelta(filePath, previousOffset, out var data, out var nextOffset))
                return;
            _fileOffsets[filePath] = nextOffset;
            if (data.Length == 0)
                return;
            OnDataReady?.Invoke(data);
            BackupChunk(filePath, data);
            AnalyzeStatus(data);
            Log($"Journal payload detected: {Path.GetFileName(filePath)} ({data.Length} bytes).");
            }
            private bool IsSupportedWatchFile(string filePath)
            {
            var fileName = Path.GetFileName(filePath);
            if (string.IsNullOrWhiteSpace(fileName))
                return false;
            return _watchAtmType switch
            {
                ATMType.NCR => Constants.EJPatterns.NCRFiles.Any(value => fileName.Equals(value, StringComparison.OrdinalIgnoreCase)),
                ATMType.GRG => fileName.StartsWith(Constants.EJPatterns.GRGPrefix, StringComparison.OrdinalIgnoreCase),
                ATMType.WN => fileName.StartsWith(Constants.EJPatterns.WNPrefix, StringComparison.OrdinalIgnoreCase) || fileName.EndsWith(".ej", StringComparison.OrdinalIgnoreCase),
                ATMType.DieboldNixdorf => fileName.StartsWith(Constants.EJPatterns.DNPrefix, StringComparison.OrdinalIgnoreCase) || fileName.EndsWith(".jrn", StringComparison.OrdinalIgnoreCase),
                ATMType.Hyosung => fileName.StartsWith(Constants.EJPatterns.HYPrefix, StringComparison.OrdinalIgnoreCase),
                _ => Constants.EJPatterns.ValidExtensions.Any(ext => fileName.EndsWith(ext, StringComparison.OrdinalIgnoreCase))
            };
            }
            private void AnalyzeStatus(byte[] payload)
            {
            var text = Encoding.UTF8.GetString(payload).ToUpperInvariant();
            if (text.Contains("SUPERVISOR") || text.Contains("SUPV"))
            {
                OnStatusChanged?.Invoke(_watchAtmId, ATMStatus.Supervisor);
                return;
            }
            if (text.Contains("FAULT") || text.Contains("ERROR"))
            {
                OnStatusChanged?.Invoke(_watchAtmId, ATMStatus.CriticalFault);
                return;
            }
            if (text.Contains("OUT OF SERVICE") || text.Contains("OOS"))
            {
                OnStatusChanged?.Invoke(_watchAtmId, ATMStatus.OutOfService);
                return;
            }
            if (text.Contains("IN SERVICE") || text.Contains("READY"))
            {
                OnStatusChanged?.Invoke(_watchAtmId, ATMStatus.InService);
            }
            }
            private void BackupChunk(string sourceFilePath, byte[] payload)
            {
            try
            {
                var backupRoot = Path.Combine(GetBackupRoot(), DateTime.UtcNow.ToString("yyyy-MM"));
                Directory.CreateDirectory(backupRoot);
                var fileName = Path.GetFileName(sourceFilePath) + "." + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff") + ".bin";
                File.WriteAllBytes(Path.Combine(backupRoot, fileName), payload);
            }
            catch (Exception ex)
            {
                Log("Backup write failed: " + ex.Message);
            }
            }
            private string GetBackupRoot()
            {
            var baseRoot = AppConstants.DefaultClientOutboxPath;
            var atm = string.IsNullOrWhiteSpace(_watchAtmId) ? "UNKNOWN" : _watchAtmId;
            return Path.Combine(baseRoot, "JournalBackups", atm);
            }
            private void ReportProgress(string atmId, string fileName, long bytesSent, long currentBytes, long totalBytes, SyncStatus status)
            {
            OnSyncProgress?.Invoke(this, new LiveSyncProgress
            {
                ATM_ID = string.IsNullOrWhiteSpace(atmId) ? _watchAtmId : atmId,
                FileName = fileName ?? string.Empty,
                BytesSent = Math.Max(bytesSent, currentBytes),
                TotalBytes = Math.Max(0, totalBytes),
                Status = status,
                UpdatedAtUtc = DateTime.UtcNow
            });
            }
            private static string ComputeFileMd5(string filePath)
            {
            using var stream = File.OpenRead(filePath);
            using var md5 = System.Security.Cryptography.MD5.Create();
            var hash = md5.ComputeHash(stream);
            return Convert.ToHexString(hash);
            }
            private void Log(string message)
            {
            AppLogger.Instance.Info(message, "JournalProcessor");
            OnLogMessage?.Invoke(message);
            }
            public void Dispose()
            {
            Stop();
            }
            public void Pause()
            {
            _paused = true;
            AppLogger.Instance.Info("JournalProcessor paused", "Processor");
            }
            public void Resume()
            {
            _paused = false;
            AppLogger.Instance.Info("JournalProcessor resumed", "Processor");
            }
            private void ProcessLoop()
            {
            while (_running)
            {
                try
                {
                if (_paused || !_network.IsConnected)
                {
                    Thread.Sleep(500);
                    continue;
                }
                if (_outbox.TryDequeue(out var item))
                {
                    if (!item.IsReadyToSend)
                    {
                    _outbox.Enqueue(item);
                    Thread.Sleep(100);
                    continue;
                    }
                    SendItem(item);
                }
                else
                {
                    Thread.Sleep(200);
                }
                }
                catch (Exception ex)
                {
                AppLogger.Instance.Error(ex, "JournalProcessor.ProcessLoop");
                Thread.Sleep(1000);
                }
            }
            }
            private void SendItem(JournalOutboxItem item)
            {
            try
            {
                AppLogger.Instance.Info($"Sending: {item.FileName} [{item.DataSize / 1024.0:F1} KB] retry={item.RetryCount}", "Processor");
                var checksum   = SecurityHelper.MD5Hash(item.Data);
                var totalBytes = (long)item.Data.Length;
                long sentBytes = 0;
                // تحديث التقدم — بداية
                ReportProgress(item.FileName, 0, sentBytes, totalBytes);
                var ok = _network.SendJournalFile(item.FileName, item.Data, item.Offset, checksum);
                if (ok)
                {
                TotalSent++;
                _outbox.MarkCompleted(item.ItemId);
                OnItemCompleted?.Invoke(this, item);
                ReportProgress(item.FileName, 100, totalBytes, totalBytes);
                }
                else
                {
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                TotalFailed++;
                OnItemFailed?.Invoke(this, item);
                AppLogger.Instance.Warning($"Send failed: {item.FileName} - retry in {delay}ms", "Processor");
                }
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex, "JournalProcessor.SendItem");
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                OnItemFailed?.Invoke(this, item);
            }
            }
            private void ReportProgress(string fileName, int percent, long sentBytes, long totalBytes)
            {
            OnSyncProgress?.Invoke(this, new LiveSyncProgress
            {
                ATMId     = "",
                FileName  = fileName,
                Percent   = percent,
                BytesSent = sentBytes,
                TotalBytes = totalBytes,
                StateLabel = percent == 100 ? "اكتمل" : "قيد الإرسال",
                StateIcon  = percent == 100 ? "Done" : "Sync",
                UpdatedAt  = DateTime.UtcNow
            });
            }
            public void Dispose() => Stop();
            private Dictionary<string, long> _filePositions = new Dictionary<string, long>();
            public void StartMonitoring()
            {
            _isRunning = true;
            new Thread(MonitoringLoop).Start();
            }
            private void MonitoringLoop()
            {
            while (_isRunning)
            {
                try
                {
                if (_atmType == ATMType.NCR)
                {
                    foreach (var fileName in Constants.EJPatterns.NCRFiles)
                    {
                    ProcessFile(Path.Combine(_sourcePath, fileName));
                    }
                }
                else
                {
                    foreach (var file in Directory.GetFiles(_sourcePath, "*.LOG"))
                    {
                    string fileName = Path.GetFileName(file);
                    if (fileName.StartsWith(Constants.EJPatterns.GRGPrefix) || 
                        fileName.StartsWith(Constants.EJPatterns.TracePrefix))
                    {
                        ProcessFile(file);
                    }
                    }
                }
                }
                catch { }
                Thread.Sleep(1000);
            }
            }
            private void ProcessFile(string path)
            {
            if (!File.Exists(path)) return;
            string fileName = Path.GetFileName(path);
            using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            {
                long lastPos = _filePositions.ContainsKey(fileName) ? _filePositions[fileName] : 0;
                if (fs.Length < lastPos) lastPos = 0;
                if (fs.Length > lastPos)
                {
                fs.Position = lastPos;
                byte[] buffer = new byte[fs.Length - lastPos];
                fs.Read(buffer, 0, buffer.Length);
                // Mirror to backup
                string backupFile = Path.Combine(_backupPath, fileName);
                File.AppendAllBytes(backupFile, buffer);
                // Calculate MD5
                string md5 = CalculateMD5(buffer);
                OnNewDataCaptured?.Invoke(buffer, fileName, md5);
                _filePositions[fileName] = fs.Length;
                }
            }
            }
            private string CalculateMD5(byte[] data)
            {
            using (var md5 = MD5.Create())
            {
                byte[] hash = md5.ComputeHash(data);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
            }
            private void SendItem(JournalOutboxItem item)
            {
            try
            {
                AppLogger.Instance.Info($"⟳ Sending: {item.FileName} [{item.DataSize / 1024.0:F1} KB] retry={item.RetryCount}", "Processor");
                // ضغط البيانات
                var compressed = SecurityHelper.Compress(item.Data);
                var checksum   = SecurityHelper.MD5Hash(item.Data); // Checksum على البيانات الأصلية (قبل الضغط)
                var totalBytes = (long)compressed.Length;
                long sentBytes = 0;
                var chunkSize  = (int)AppConstants.ChunkSizeBytes;
                // تحديث التقدم — بداية
                ReportProgress(item.FileName, 0, sentBytes, totalBytes);
                var ok = _network.SendJournalFile(item.FileName, compressed, item.Offset, checksum);
                if (ok)
                {
                TotalSent++;
                _outbox.MarkCompleted(item.ItemId);
                OnItemCompleted?.Invoke(this, item);
                ReportProgress(item.FileName, 100, totalBytes, totalBytes);
                }
                else
                {
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                TotalFailed++;
                OnItemFailed?.Invoke(this, item);
                AppLogger.Instance.Warning($"✗ Send failed: {item.FileName} — retry in {delay}ms", "Processor");
                }
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex, "JournalProcessor.SendItem");
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                OnItemFailed?.Invoke(this, item);
            }
            }
            private void ReportProgress(string fileName, int percent, long sentBytes, long totalBytes)
            {
            OnSyncProgress?.Invoke(this, new LiveSyncProgress
            {
                ATMId     = "",
                FileName  = fileName,
                Percent   = percent,
                BytesSent = sentBytes,
                TotalBytes = totalBytes,
                StateLabel = percent == 100 ? "اكتمل" : "قيد الإرسال",
                StateIcon  = percent == 100 ? "✅" : "🔄",
                UpdatedAt  = DateTime.UtcNow
            });
            }
            public void StartMonitoring()
            {
            string dir = Path.GetDirectoryName(_sourcePath);
            string filter = Path.GetFileName(_sourcePath);
            if (_atmType == ATMType.NCR)
            {
                // NCR uses fixed files
                MonitorFile(_sourcePath);
            }
            else
            {
                // GRG/WN use daily files
                _watcher = new FileSystemWatcher(dir);
                _watcher.NotifyFilter = NotifyFilters.FileName | NotifyFilters.Size | NotifyFilters.LastWrite;
                _watcher.Filter = "*.LOG";
                _watcher.Created += (s, e) => ProcessFile(e.FullPath);
                _watcher.Changed += (s, e) => ProcessFile(e.FullPath);
                _watcher.EnableRaisingEvents = true;
            }
            }
            private void MonitorFile(string path)
            {
            // Logic for continuous monitoring of a single file
            new Thread(() =>
            {
                while (true)
                {
                ProcessFile(path);
                Thread.Sleep(1000);
                }
            }).Start();
            }
            private void ProcessFile(string path)
            {
            try
            {
                if (!File.Exists(path)) return;
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                if (fs.Length < _lastPosition) _lastPosition = 0; // File truncated/reset
                if (fs.Length > _lastPosition)
                {
                    fs.Position = _lastPosition;
                    byte[] buffer = new byte[fs.Length - _lastPosition];
                    fs.Read(buffer, 0, buffer.Length);
                    // Save to local backup (Mirroring)
                    string backupFile = Path.Combine(_backupPath, Path.GetFileName(path) + ".bak");
                    using (FileStream bfs = new FileStream(backupFile, FileMode.Append, FileAccess.Write, FileShare.ReadWrite))
                    {
                    bfs.Write(buffer, 0, buffer.Length);
                    }
                    // Trigger event for network transmission
                    OnNewDataCaptured?.Invoke(buffer, Path.GetFileName(path));
                    _lastPosition = fs.Size;
                }
                }
            }
            catch (Exception ex)
            {
                // Log error
            }
            }
            private bool DirectoryExists(string path) => Directory.Exists(path);
