                    _watcher?.Dispose();
                    _watcher = null;
                }
                catch
                {
                }
    
                if (_processorThread is { IsAlive: true })
                {
                    try
                    {
                    _processorThread.Join(TimeSpan.FromSeconds(2));
                    }
                    catch
                    {
                    }
                }
    
