        /// <summary>
        /// معالج الجورنال — حلقة إرسال مستمرة تأخذ من Outbox وترسل للسيرفر
        /// يتعامل مع: CHUNK_ACK (T-08), إعادة المحاولة بـ Backoff (L-05)
        /// يتبع الأولويات: بيانات جديدة → قائمة انتظار → إعادة إرسال الفاشلة
        /// </summary>
        public class JournalProcessor : IDisposable
        {
            private readonly NetworkManager _network;
            private readonly JournalOutbox  _outbox;
            private Thread   _processorThread;
            private volatile bool _running;
            private volatile bool _paused;
    
            private readonly RetryPolicy _retry;
    
            public event EventHandler<LiveSyncProgress>  OnSyncProgress;
            public event EventHandler<JournalOutboxItem> OnItemCompleted;
            public event EventHandler<JournalOutboxItem> OnItemFailed;
    
            // إحصائيات
            public int  TotalSent      { get; private set; }
            public int  TotalFailed    { get; private set; }
            public bool IsRunning      => _running;
            public bool IsPaused       => _paused;
    
            public JournalProcessor(NetworkManager network, JournalOutbox outbox)
            {
            _network = network;
            _outbox  = outbox;
            _retry   = RetryPolicy.LAN;
            }
    
            public void Start()
            {
            if (_running) return;
            _running = true;
            _processorThread = new Thread(ProcessLoop)
            {
                IsBackground = true,
                Name         = "EJLive.JournalProcessor"
            };
            _processorThread.Start();
            AppLogger.Instance.Info("JournalProcessor started", "Processor");
            }
    
            public void Stop()
            {
            _running = false;
            AppLogger.Instance.Info("JournalProcessor stopped", "Processor");
            }
    
            public void Pause()  { _paused = true;  AppLogger.Instance.Info("JournalProcessor paused",  "Processor"); }
            public void Resume() { _paused = false; AppLogger.Instance.Info("JournalProcessor resumed", "Processor"); }
    
            public void ForceSendNow()
            {
            // يمكن تعيين حدث يجبر الـ Processor على الإرسال فورًا
            _paused = false;
            }
    
            // ==========================================
            // حلقة المعالجة الرئيسية
            // ==========================================
    
            private void ProcessLoop()
            {
            while (_running)
            {
                try
                {
                if (_paused || !_network.IsConnected)
                {
                    Thread.Sleep(500);
                    continue;
                }
    
                if (_outbox.TryDequeue(out var item))
                {
                    if (!item.IsReadyToSend)
                    {
                    _outbox.Enqueue(item);
                    Thread.Sleep(100);
                    continue;
                    }
    
                    SendItem(item);
                }
                else
                {
                    Thread.Sleep(200);
                }
                }
                catch (Exception ex)
                {
                AppLogger.Instance.Error(ex, "JournalProcessor.ProcessLoop");
                Thread.Sleep(1000);
                }
            }
            }
    
            private void SendItem(JournalOutboxItem item)
            {
            try
            {
                AppLogger.Instance.Info($"⟳ Sending: {item.FileName} [{item.DataSize / 1024.0:F1} KB] retry={item.RetryCount}", "Processor");
    
                // ضغط البيانات
                var compressed = SecurityHelper.Compress(item.Data);
                var checksum   = SecurityHelper.MD5Hash(item.Data); // Checksum على البيانات الأصلية (قبل الضغط)
                var totalBytes = (long)compressed.Length;
                long sentBytes = 0;
                var chunkSize  = (int)AppConstants.ChunkSizeBytes;
    
                // تحديث التقدم — بداية
                ReportProgress(item.FileName, 0, sentBytes, totalBytes);
    
                var ok = _network.SendJournalFile(item.FileName, compressed, item.Offset, checksum);
    
                if (ok)
                {
                TotalSent++;
                _outbox.MarkCompleted(item.ItemId);
                OnItemCompleted?.Invoke(this, item);
                ReportProgress(item.FileName, 100, totalBytes, totalBytes);
                }
                else
                {
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                TotalFailed++;
                OnItemFailed?.Invoke(this, item);
                AppLogger.Instance.Warning($"✗ Send failed: {item.FileName} — retry in {delay}ms", "Processor");
                }
            }
            catch (Exception ex)
            {
                AppLogger.Instance.Error(ex, "JournalProcessor.SendItem");
                var delay = _retry.ComputeDelay(item.RetryCount + 1);
                _outbox.RetryItem(item.ItemId, delay);
                OnItemFailed?.Invoke(this, item);
            }
            }
    
            private void ReportProgress(string fileName, int percent, long sentBytes, long totalBytes)
            {
            OnSyncProgress?.Invoke(this, new LiveSyncProgress
            {
                ATMId     = "",
                FileName  = fileName,
                Percent   = percent,
                BytesSent = sentBytes,
                TotalBytes = totalBytes,
                StateLabel = percent == 100 ? "اكتمل" : "قيد الإرسال",
                StateIcon  = percent == 100 ? "✅" : "🔄",
                UpdatedAt  = DateTime.UtcNow
            });
            }
    
            public void Dispose() => Stop();
        }
        public class JournalProcessor
        {
            private string _sourcePath;
            private string _backupPath;
            private ATMType _atmType;
            private Dictionary<string, long> _filePositions = new Dictionary<string, long>();
            private bool _isRunning;
    
            public event Action<byte[], string, string> OnNewDataCaptured;
    
            public JournalProcessor(ATMType type, string source, string backup)
            {
            _atmType = type;
            _sourcePath = source;
            _backupPath = backup;
    
            if (!Directory.Exists(_backupPath))
                Directory.CreateDirectory(_backupPath);
            }
    
            public void StartMonitoring()
            {
            _isRunning = true;
            new Thread(MonitoringLoop).Start();
            }
    
            private void MonitoringLoop()
            {
            while (_isRunning)
            {
                try
                {
                if (_atmType == ATMType.NCR)
                {
                    foreach (var fileName in Constants.EJPatterns.NCRFiles)
                    {
                    ProcessFile(Path.Combine(_sourcePath, fileName));
                    }
                }
                else
                {
                    foreach (var file in Directory.GetFiles(_sourcePath, "*.LOG"))
                    {
                    string fileName = Path.GetFileName(file);
                    if (fileName.StartsWith(Constants.EJPatterns.GRGPrefix) || 
                        fileName.StartsWith(Constants.EJPatterns.TracePrefix))
                    {
                        ProcessFile(file);
                    }
                    }
                }
                }
                catch { }
                Thread.Sleep(1000);
            }
            }
    
            private void ProcessFile(string path)
            {
            if (!File.Exists(path)) return;
            string fileName = Path.GetFileName(path);
    
            using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            {
                long lastPos = _filePositions.ContainsKey(fileName) ? _filePositions[fileName] : 0;
                if (fs.Length < lastPos) lastPos = 0;
    
                if (fs.Length > lastPos)
                {
                fs.Position = lastPos;
                byte[] buffer = new byte[fs.Length - lastPos];
                fs.Read(buffer, 0, buffer.Length);
    
                // Mirror to backup
                string backupFile = Path.Combine(_backupPath, fileName);
                File.AppendAllBytes(backupFile, buffer);
    
                // Calculate MD5
                string md5 = CalculateMD5(buffer);
    
                OnNewDataCaptured?.Invoke(buffer, fileName, md5);
                _filePositions[fileName] = fs.Length;
                }
            }
            }
    
            private string CalculateMD5(byte[] data)
            {
            using (var md5 = MD5.Create())
            {
                byte[] hash = md5.ComputeHash(data);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
            }
    
            public void Stop() => _isRunning = false;
        }
