        private void OnFileChanged(object sender, FileSystemEventArgs e)
        {
            if (!IsJournalFile(e.FullPath)) return;
            Task.Run(() =>
            {
            try { ProcessFileWithShadowCopy(e.FullPath); }
            catch (Exception ex)
            {
                ProcessingError?.Invoke(this, ex);
                Logger.Error($"Error processing {e.Name}: {ex.Message}", "JournalProcessor", ex);
            }
            });
        }
    
        private void OnFileRenamed(object sender, RenamedEventArgs e)
        {
            OnFileChanged(sender, new FileSystemEventArgs(WatcherChangeTypes.Created,
            Path.GetDirectoryName(e.FullPath)!, e.Name!));
        }
    
        private async Task ProcessExistingFiles(CancellationToken ct)
        {
            try
            {
            foreach (var file in Directory.GetFiles(_config.JournalSourcePath, "*.*", SearchOption.TopDirectoryOnly))
            {
                if (ct.IsCancellationRequested) break;
                if (!IsJournalFile(file)) continue;
                try { ProcessFileWithShadowCopy(file); }
                catch (Exception ex) { Logger.Error($"Error processing {file}: {ex.Message}", "JournalProcessor", ex); }
                await Task.Delay(100, ct);
            }
            }
            catch (Exception ex) { Logger.Error($"ProcessExistingFiles error: {ex.Message}", "JournalProcessor", ex); }
        }
    
        private void ProcessFileWithShadowCopy(string filePath)
        {
            lock (_lock)
            {
            var fileName = Path.GetFileName(filePath);
            var shadowPath = Path.Combine(Path.GetTempPath(), $"ejlive_shadow_{Guid.NewGuid():N}.tmp");
            try
            {
                using (var src = new FileStream(filePath, FileMode.Open, FileAccess.Read,
                FileShare.ReadWrite | FileShare.Delete, 4096, FileOptions.SequentialScan))
                using (var dst = new FileStream(shadowPath, FileMode.Create, FileAccess.Write,
                FileShare.None, 4096, FileOptions.SequentialScan))
                src.CopyTo(dst);
    
                long pos = _filePositions.GetValueOrDefault(fileName, 0);
                var newPos = ProcessJournalFile(shadowPath, pos);
                _filePositions[fileName] = newPos;
    
                var backup = Path.Combine(_config.LocalBackupPath, fileName);
                File.Copy(shadowPath, backup, overwrite: true);
                FileProcessed?.Invoke(this, fileName);
                Logger.Info($"Processed: {fileName} (entries: {TotalEntriesParsed})", "JournalProcessor");
            }
            finally { try { if (File.Exists(shadowPath)) File.Delete(shadowPath); } catch { } }
            }
        }
    
        private long ProcessJournalFile(string filePath, long start)
        {
            var lines = File.ReadAllLines(filePath);
            var pos = start;
            for (long i = start; i < lines.Length; i++)
            {
            if (string.IsNullOrWhiteSpace(lines[i])) continue;
            var entry = ParseJournalLine(lines[i], i);
            if (entry != null) { TotalEntriesParsed++; JournalEntryParsed?.Invoke(this, entry); }
            pos = i + 1;
            }
            return pos;
        }
    
        private JournalEntry? ParseJournalLine(string line, long lineNum)
        {
            try
            {
            return _config.ATMType switch
            {
                ATMTypeEnum.NCR => ParseNCR(line, lineNum),
                ATMTypeEnum.GRG => ParseGRG(line, lineNum),
                ATMTypeEnum.WN => ParseWN(line, lineNum),
                _ => null
            };
            }
            catch (Exception ex) { Logger.Warning($"Parse error line {lineNum}: {ex.Message}", "JournalProcessor"); return null; }
        }
    
        private JournalEntry? ParseNCR(string line, long lineNum)
        {
            var parts = line.Split('|');
            if (parts.Length < 2) return null;
            if (DateTime.TryParse(parts[0], out var ts))
            return new JournalEntry { LineNumber = lineNum, Timestamp = ts, EventType = parts.ElementAtOrDefault(1) ?? "UNKNOWN", Data = parts.ElementAtOrDefault(2) ?? "", Response = parts.ElementAtOrDefault(3) ?? "", RawLine = line, ATMType = ATMTypeEnum.NCR };
            return null;
        }
    
        private JournalEntry? ParseGRG(string line, long lineNum)
        {
            var m = Regex.Match(line, @"\[(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\]\s*\[(\w+)\]\s*(.+)");
            if (m.Success)
            return new JournalEntry { LineNumber = lineNum, Timestamp = DateTime.Parse(m.Groups[1].Value), EventType = m.Groups[2].Value, Data = m.Groups[3].Value, RawLine = line, ATMType = ATMTypeEnum.GRG };
            return null;
        }
    
        private JournalEntry? ParseWN(string line, long lineNum)
        {
            var parts = line.Split(';');
            if (parts.Length >= 2)
            return new JournalEntry { LineNumber = lineNum, Timestamp = DateTime.Now, EventType = parts.ElementAtOrDefault(2) ?? "UNKNOWN", Data = string.Join(";", parts.Skip(3)), RawLine = line, ATMType = ATMTypeEnum.WN };
            return null;
        }
    
        private bool IsJournalFile(string path)
        {
            var ext = Path.GetExtension(path).ToLowerInvariant();
            var name = Path.GetFileName(path).ToLowerInvariant();
            return ext switch
            {
            ".log" => name.Contains("ej") || name.Contains("trace"),
            ".lob" => name.Contains("ej"),
            ".trace" => true,
            ".txt" => name.Contains("journal") || name.Contains("ej"),
            _ => false
            };
        }
    
        public void Dispose() { Stop(); _cts?.Dispose(); _watcher?.Dispose(); }
        }
    
