            public void StartMonitoring()
            {
            string dir = Path.GetDirectoryName(_sourcePath);
            string filter = Path.GetFileName(_sourcePath);
    
            if (_atmType == ATMType.NCR)
            {
                // NCR uses fixed files
                MonitorFile(_sourcePath);
            }
            else
            {
                // GRG/WN use daily files
                _watcher = new FileSystemWatcher(dir);
                _watcher.NotifyFilter = NotifyFilters.FileName | NotifyFilters.Size | NotifyFilters.LastWrite;
                _watcher.Filter = "*.LOG";
                _watcher.Created += (s, e) => ProcessFile(e.FullPath);
                _watcher.Changed += (s, e) => ProcessFile(e.FullPath);
                _watcher.EnableRaisingEvents = true;
            }
            }
    
    
            // Variant: d:\EJLIVE\EJlive_Reference_Projects\Ejliv-ATM-20\EJLive.Client\JournalProcessor.cs
            private void ProcessFile(string path)
            {
            try
            {
                if (!File.Exists(path)) return;
    
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                if (fs.Length < _lastPosition) _lastPosition = 0; // File truncated/reset
    
                if (fs.Length > _lastPosition)
                {
                    fs.Position = _lastPosition;
                    byte[] buffer = new byte[fs.Length - _lastPosition];
                    fs.Read(buffer, 0, buffer.Length);
    
                    // Save to local backup (Mirroring)
                    string backupFile = Path.Combine(_backupPath, Path.GetFileName(path) + ".bak");
                    using (FileStream bfs = new FileStream(backupFile, FileMode.Append, FileAccess.Write, FileShare.ReadWrite))
                    {
                    bfs.Write(buffer, 0, buffer.Length);
                    }
    
                    // Trigger event for network transmission
                    OnNewDataCaptured?.Invoke(buffer, Path.GetFileName(path));
    
                    _lastPosition = fs.Size;
                }
                }
            }
            catch (Exception ex)
            {
                // Log error
            }
            }
    
    
