        {
            private string _ejPath;
            private ATMType _atmType;
            private string _atmId;
            private long _lastProcessedSize;
            private FileSystemWatcher _watcher;
            private bool _isRunning;
    
            public event Action<string> OnLogMessage;
            public event Action<byte[]> OnDataReady;
            public event Action<string, ATMStatus> OnStatusChanged;
    
            public JournalProcessor(string ejPath, ATMType atmType, string atmId)
            {
            _ejPath = ejPath;
            _atmType = atmType;
            _atmId = atmId;
            _lastProcessedSize = 0;
            }
    
            public void Start()
            {
            _isRunning = true;
            Log("JournalProcessor started for " + _atmId + " (" + _atmType.ToString() + ")");
            Log("Monitoring path: " + _ejPath);
    
            if (!Directory.Exists(_ejPath))
            {
                Log("WARNING: EJ path does not exist: " + _ejPath);
                return;
            }
    
            // Initial scan
            ScanExistingFiles();
    
            // Setup FileSystemWatcher for real-time monitoring
            _watcher = new FileSystemWatcher(_ejPath);
            _watcher.Filter = GetFilter();
            _watcher.NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.Size | NotifyFilters.FileName;
            _watcher.Changed += OnFileChanged;
            _watcher.Created += OnFileCreated;
            _watcher.EnableRaisingEvents = true;
    
            Log("FileSystemWatcher active.");
            }
    
            public void Stop()
            {
            _isRunning = false;
            if (_watcher != null)
            {
                _watcher.EnableRaisingEvents = false;
                _watcher.Dispose();
                _watcher = null;
            }
            Log("JournalProcessor stopped.");
            }
    
            private string GetFilter()
            {
            switch (_atmType)
            {
                case ATMType.NCR: return "EJDATA.*";
                case ATMType.GRG: return "EJ*.log";
                case ATMType.WN: return "EJ*.log";
                default: return "*.*";
            }
            }
    
            private void ScanExistingFiles()
            {
            Log("Scanning existing EJ files...");
            string[] files = Directory.GetFiles(_ejPath, GetFilter());
            foreach (string file in files)
            {
                ProcessFile(file);
            }
            Log("Initial scan complete. Found " + files.Length + " file(s).");
            }
    
            private void OnFileChanged(object sender, FileSystemEventArgs e)
            {
            if (!_isRunning) return;
            Thread.Sleep(500); // Wait for file write to complete
            ProcessFile(e.FullPath);
            }
    
            private void OnFileCreated(object sender, FileSystemEventArgs e)
            {
            if (!_isRunning) return;
            Thread.Sleep(1000); // Wait for file creation to complete
            Log("New EJ file detected: " + e.Name);
            ProcessFile(e.FullPath);
            }
    
            private void ProcessFile(string filePath)
            {
            try
            {
                if (!File.Exists(filePath)) return;
    
                FileInfo fi = new FileInfo(filePath);
                if (fi.Length <= _lastProcessedSize && fi.FullName == GetPrimaryFile())
                return; // No new data
    
                byte[] newData;
                using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                if (fi.FullName == GetPrimaryFile())
                {
                    fs.Seek(_lastProcessedSize, SeekOrigin.Begin);
                    newData = new byte[fi.Length - _lastProcessedSize];
                    fs.Read(newData, 0, newData.Length);
                    _lastProcessedSize = fi.Length;
                }
                else
                {
                    newData = new byte[fi.Length];
                    fs.Read(newData, 0, newData.Length);
                }
                }
    
                if (newData.Length > 0)
                {
                Log("Processing " + newData.Length + " bytes from " + Path.GetFileName(filePath));
                AnalyzeContent(Encoding.Default.GetString(newData));
    
                // Backup locally
                BackupLocally(filePath, newData);
    
                // Notify data ready for sending
                if (OnDataReady != null)
                    OnDataReady(newData);
                }
            }
            catch (Exception ex)
            {
                Log("ERROR processing file: " + ex.Message);
            }
            }
    
            private string GetPrimaryFile()
            {
            switch (_atmType)
            {
                case ATMType.NCR: return Path.Combine(_ejPath, "EJDATA.LOG");
                case ATMType.GRG: return Path.Combine(_ejPath, "EJ" + DateTime.Now.ToString("yyyyMMdd") + ".log");
                case ATMType.WN: return Path.Combine(_ejPath, "EJ" + DateTime.Now.ToString("yyyyMMdd") + ".log");
                default: return "";
            }
            }
    
            private void AnalyzeContent(string content)
            {
            // Analyze journal content for ATM status
            string upper = content.ToUpper();
    
            if (upper.Contains("SUPERVISOR") || upper.Contains("SUPV MODE"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.ConnectedOnly);
                Log("Status: Supervisor Mode detected");
            }
            else if (upper.Contains("FAULT") || upper.Contains("ERROR") || upper.Contains("HARDWARE"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.CriticalFault);
                Log("Status: Fault detected in journal");
            }
            else if (upper.Contains("OUT OF SERVICE") || upper.Contains("OOS"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.OutOfService);
                Log("Status: Out of Service");
            }
            else if (upper.Contains("IN SERVICE") || upper.Contains("READY"))
            {
                OnStatusChanged?.Invoke(_atmId, ATMStatus.InService);
                Log("Status: In Service");
            }
            }
    
            private void BackupLocally(string sourceFile, byte[] data)
            {
            try
            {
                string backupDir = Path.Combine(Constants.Paths.LocalBackupBase, _atmId, DateTime.Now.ToString("yyyy-MM"));
                if (!Directory.Exists(backupDir))
                Directory.CreateDirectory(backupDir);
    
                string backupFile = Path.Combine(backupDir, Path.GetFileName(sourceFile));
                File.WriteAllBytes(backupFile, data);
            }
            catch (Exception ex)
            {
                Log("Backup error: " + ex.Message);
            }
            }
    
            /// <summary>
            /// Three-way verification: Source -> Local Backup -> Server
            /// </summary>
            public bool VerifyIntegrity(string filePath)
            {
            try
            {
                string sourceHash = ComputeMD5(filePath);
                string backupPath = Path.Combine(Constants.Paths.LocalBackupBase, _atmId, DateTime.Now.ToString("yyyy-MM"), Path.GetFileName(filePath));
    
                if (!File.Exists(backupPath))
                {
                Log("Verification FAILED: Backup file not found.");
                return false;
                }
    
                string backupHash = ComputeMD5(backupPath);
                bool match = sourceHash == backupHash;
                Log("Verification " + (match ? "PASSED" : "FAILED") + ": Source=" + sourceHash.Substring(0, 8) + " Backup=" + backupHash.Substring(0, 8));
                return match;
            }
            catch (Exception ex)
            {
                Log("Verification error: " + ex.Message);
                return false;
            }
            }
    
            private string ComputeMD5(string filePath)
            {
            using (var md5 = MD5.Create())
            using (var stream = File.OpenRead(filePath))
            {
                byte[] hash = md5.ComputeHash(stream);
                StringBuilder sb = new StringBuilder();
                foreach (byte b in hash) sb.Append(b.ToString("x2"));
                return sb.ToString();
            }
            }
    
            private void Log(string message)
            {
            OnLogMessage?.Invoke(message);
            }
        }
    
        public partial class JournalEntry
        {
        }
    }
    
    namespace EJLive.Core.Parsers
    {
        public class JournalEntry
        {
        public long LineNumber { get; set; }
        public DateTime Timestamp { get; set; }
        public string EventType { get; set; } = string.Empty;
        public string Data { get; set; } = string.Empty;
        public string Response { get; set; } = string.Empty;
        public string RawLine { get; set; } = string.Empty;
        public ATMType ATMType { get; set; }
        public bool IsError => EventType.Contains("ERROR", StringComparison.OrdinalIgnoreCase) ||
                    EventType.Contains("FAULT", StringComparison.OrdinalIgnoreCase);
        public bool IsTransaction => EventType.Contains("TRANS", StringComparison.OrdinalIgnoreCase) ||
                        EventType.Contains("CASH", StringComparison.OrdinalIgnoreCase);
        }
        public class JournalEntry
        {
        public long LineNumber { get; set; }
        public DateTime Timestamp { get; set; }
        public string EventType { get; set; } = string.Empty;
        public string Data { get; set; } = string.Empty;
        public string Response { get; set; } = string.Empty;
        public string RawLine { get; set; } = string.Empty;
        public ATMTypeEnum ATMType { get; set; }
        public bool IsError => EventType.Contains("ERROR", StringComparison.OrdinalIgnoreCase) || EventType.Contains("FAULT", StringComparison.OrdinalIgnoreCase);
        public bool IsTransaction => EventType.Contains("TRANS", StringComparison.OrdinalIgnoreCase) || EventType.Contains("CASH", StringComparison.OrdinalIgnoreCase);
        }
        public class JournalProcessor : IDisposable
        {
        private FileSystemWatcher? _watcher;
        private readonly ATMConfig _config;
        private CancellationTokenSource? _cts;
        private Task? _processTask;
        private readonly Dictionary<string, long> _filePositions = new();
        private readonly object _lock = new();
    
        public event EventHandler<JournalEntry>? JournalEntryParsed;
        public event EventHandler<string>? FileProcessed;
        public event EventHandler<Exception>? ProcessingError;
    
        public bool IsRunning { get; private set; }
        public long TotalEntriesParsed { get; private set; } = 0;
    
        public JournalProcessor(ATMConfig config)
        {
            _config = config;
        }
    
        public void Start()
        {
            if (IsRunning) return;
    
            _cts = new CancellationTokenSource();
            IsRunning = true;
    
            // Ensure directories exist
            Directory.CreateDirectory(_config.JournalSourcePath);
            Directory.CreateDirectory(_config.LocalBackupPath);
    
            // Setup file watcher
            _watcher = new FileSystemWatcher(_config.JournalSourcePath)
            {
            NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.FileName | NotifyFilters.Size,
            Filter = "*.*",
            EnableRaisingEvents = true
            };
    
            _watcher.Changed += OnFileChanged;
            _watcher.Created += OnFileChanged;
            _watcher.Renamed += OnFileRenamed;
    
            // Start background processing
            _processTask = Task.Run(() => ProcessExistingFiles(_cts.Token));
    
            Logger.Info($"JournalProcessor started watching: {_config.JournalSourcePath}", "JournalProcessor");
        }
    
        public void Stop()
        {
            IsRunning = false;
            _cts?.Cancel();
            _watcher?.Dispose();
    
            if (_processTask != null)
            try { _processTask.Wait(TimeSpan.FromSeconds(10)); } catch { }
    
            Logger.Info("JournalProcessor stopped", "JournalProcessor");
        }
    
        private void OnFileChanged(object sender, FileSystemEventArgs e)
        {
            if (!IsJournalFile(e.FullPath)) return;
    
            Task.Run(() =>
            {
            try
            {
                ProcessFileWithShadowCopy(e.FullPath);
            }
            catch (Exception ex)
            {
                ProcessingError?.Invoke(this, ex);
                Logger.Error($"Error processing {e.Name}: {ex.Message}", "JournalProcessor", ex);
            }
            });
        }
    
        private void OnFileRenamed(object sender, RenamedEventArgs e)
        {
            OnFileChanged(sender, new FileSystemEventArgs(WatcherChangeTypes.Created, 
            Path.GetDirectoryName(e.FullPath)!, e.Name!));
        }
    
        private async Task ProcessExistingFiles(CancellationToken cancellationToken)
        {
            try
            {
            var files = Directory.GetFiles(_config.JournalSourcePath, "*.*", SearchOption.TopDirectoryOnly);
            foreach (var file in files)
            {
                if (cancellationToken.IsCancellationRequested) break;
                if (!IsJournalFile(file)) continue;
    
                try
                {
                ProcessFileWithShadowCopy(file);
                }
                catch (Exception ex)
                {
                Logger.Error($"Error processing {file}: {ex.Message}", "JournalProcessor", ex);
                }
    
                await Task.Delay(100, cancellationToken);
            }
            }
            catch (Exception ex)
            {
            Logger.Error($"ProcessExistingFiles error: {ex.Message}", "JournalProcessor", ex);
            }
        }
    
        private void ProcessFileWithShadowCopy(string filePath)
        {
            lock (_lock)
            {
            var fileName = Path.GetFileName(filePath);
            var shadowPath = Path.Combine(Path.GetTempPath(), $"ejlive_shadow_{Guid.NewGuid():N}.tmp");
    
            try
            {
                // Create shadow copy using FileShare.ReadWrite to avoid locking
                using (var sourceStream = new FileStream(filePath, FileMode.Open, FileAccess.Read,
                FileShare.ReadWrite | FileShare.Delete, 4096, FileOptions.SequentialScan))
                using (var shadowStream = new FileStream(shadowPath, FileMode.Create, FileAccess.Write,
                FileShare.None, 4096, FileOptions.SequentialScan))
                {
                sourceStream.CopyTo(shadowStream);
                }
    
                // Process shadow copy
                long lastPosition = _filePositions.GetValueOrDefault(fileName, 0);
                var newPosition = ProcessJournalFile(shadowPath, lastPosition);
                _filePositions[fileName] = newPosition;
    
                // Backup to local backup folder
                var backupFile = Path.Combine(_config.LocalBackupPath, fileName);
                File.Copy(shadowPath, backupFile, overwrite: true);
    
                FileProcessed?.Invoke(this, fileName);
                Logger.Info($"Processed: {fileName} (entries: {TotalEntriesParsed})", "JournalProcessor");
            }
            finally
            {
                // Clean up shadow file
                try { if (File.Exists(shadowPath)) File.Delete(shadowPath); } catch { }
            }
            }
        }
    
        private long ProcessJournalFile(string filePath, long startPosition)
        {
            var lines = File.ReadAllLines(filePath);
            var position = startPosition;
    
            for (long i = startPosition; i < lines.Length; i++)
            {
            var line = lines[i];
            if (string.IsNullOrWhiteSpace(line)) continue;
    
            var entry = ParseJournalLine(line, i);
            if (entry != null)
            {
                TotalEntriesParsed++;
                JournalEntryParsed?.Invoke(this, entry);
            }
            position = i + 1;
            }
    
            return position;
        }
    
        private JournalEntry? ParseJournalLine(string line, long lineNumber)
        {
            try
            {
            return _config.ATMType switch
            {
                ATMType.NCR => ParseNCRLine(line, lineNumber),
                ATMType.GRG => ParseGRGLine(line, lineNumber),
                ATMType.WN => ParseWNLine(line, lineNumber),
                _ => null
            };
            }
            catch (Exception ex)
            {
            Logger.Warning($"Parse error at line {lineNumber}: {ex.Message}", "JournalProcessor");
            return null;
            }
        }
    
        private JournalEntry? ParseNCRLine(string line, long lineNumber)
        {
            // NCR Format: Timestamp|Event|Data|Response
            var parts = line.Split('|');
            if (parts.Length < 2) return null;
    
            if (DateTime.TryParse(parts[0], out var timestamp))
            {
            return new JournalEntry
            {
                LineNumber = lineNumber,
                Timestamp = timestamp,
                EventType = parts.ElementAtOrDefault(1) ?? "UNKNOWN",
                Data = parts.ElementAtOrDefault(2) ?? "",
                Response = parts.ElementAtOrDefault(3) ?? "",
                RawLine = line,
                ATMType = ATMType.NCR
            };
            }
            return null;
        }
    
        private JournalEntry? ParseGRGLine(string line, long lineNumber)
        {
            // GRG Format: [Date Time] [Level] Message
            var match = Regex.Match(line, @"\[(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\]\s*\[(\w+)\]\s*(.+)");
            if (match.Success)
            {
            return new JournalEntry
            {
                LineNumber = lineNumber,
                Timestamp = DateTime.Parse(match.Groups[1].Value),
                EventType = match.Groups[2].Value,
                Data = match.Groups[3].Value,
                RawLine = line,
                ATMType = ATMType.GRG
            };
            }
            return null;
        }
    
        private JournalEntry? ParseWNLine(string line, long lineNumber)
        {
            // WN Format: Date;Time;Event;Data
            var parts = line.Split(';');
            if (parts.Length >= 2)
            {
            return new JournalEntry
            {
                LineNumber = lineNumber,
                Timestamp = DateTime.Now, // Parse from parts if available
                EventType = parts.ElementAtOrDefault(2) ?? "UNKNOWN",
                Data = string.Join(";", parts.Skip(3)),
                RawLine = line,
                ATMType = ATMType.WN
            };
            }
            return null;
        }
    
        private bool IsJournalFile(string filePath)
        {
            var ext = Path.GetExtension(filePath).ToLowerInvariant();
            var name = Path.GetFileName(filePath).ToLowerInvariant();
    
            return ext switch
            {
            ".log" => name.Contains("ej") || name.Contains("trace"),
            ".lob" => name.Contains("ej"),
            ".trace" => true,
            ".txt" => name.Contains("journal") || name.Contains("ej"),
            _ => false
            };
        }
    
        public void Dispose()
        {
            Stop();
            _cts?.Dispose();
            _watcher?.Dispose();
        }
        }
