            try
            {
            return _config.ATMType switch
            {
                ATMTypeEnum.NCR => ParseNCR(line, lineNum),
                ATMTypeEnum.GRG => ParseGRG(line, lineNum),
                ATMTypeEnum.WN => ParseWN(line, lineNum),
                _ => null
            };
            }
            catch (Exception ex) { Logger.Warning($"Parse error line {lineNum}: {ex.Message}", "JournalProcessor"); return null; }
        }
    
        private JournalEntry? ParseNCR(string line, long lineNum)
        {
            var parts = line.Split('|');
            if (parts.Length < 2) return null;
            if (DateTime.TryParse(parts[0], out var ts))
            return new JournalEntry { LineNumber = lineNum, Timestamp = ts, EventType = parts.ElementAtOrDefault(1) ?? "UNKNOWN", Data = parts.ElementAtOrDefault(2) ?? "", Response = parts.ElementAtOrDefault(3) ?? "", RawLine = line, ATMType = ATMTypeEnum.NCR };
            return null;
        }
    
        private JournalEntry? ParseGRG(string line, long lineNum)
        {
            var m = Regex.Match(line, @"\[(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\]\s*\[(\w+)\]\s*(.+)");
            if (m.Success)
            return new JournalEntry { LineNumber = lineNum, Timestamp = DateTime.Parse(m.Groups[1].Value), EventType = m.Groups[2].Value, Data = m.Groups[3].Value, RawLine = line, ATMType = ATMTypeEnum.GRG };
            return null;
        }
    
        private JournalEntry? ParseWN(string line, long lineNum)
        {
            var parts = line.Split(';');
            if (parts.Length >= 2)
            return new JournalEntry { LineNumber = lineNum, Timestamp = DateTime.Now, EventType = parts.ElementAtOrDefault(2) ?? "UNKNOWN", Data = string.Join(";", parts.Skip(3)), RawLine = line, ATMType = ATMTypeEnum.WN };
            return null;
        }
    
        private bool IsJournalFile(string path)
        {
            var ext = Path.GetExtension(path).ToLowerInvariant();
            var name = Path.GetFileName(path).ToLowerInvariant();
            return ext switch
            {
            ".log" => name.Contains("ej") || name.Contains("trace"),
            ".lob" => name.Contains("ej"),
            ".trace" => true,
            ".txt" => name.Contains("journal") || name.Contains("ej"),
            _ => false
            };
        }
    
        public void Dispose() { Stop(); _cts?.Dispose(); _watcher?.Dispose(); }
        }
    
